/// <reference types="vite/client" />
import "./guide-style.css";

// guide.json is generated by `pnpm guide ideal`; absent until then.
const found = import.meta.glob("./data/guide.json", { eager: true, import: "default" });
const guide = Object.values(found)[0];
const root = document.getElementById("guide")!;
if (guide) {
  const pre = document.createElement("pre");
  pre.textContent = JSON.stringify(guide, null, 2);
  root.append(pre);
} else {
  root.textContent = "No guide generated yet. Run `pnpm guide ideal`.";
}
